/* ================= 65-profile.js ================= */
/* 65-profile — profile menu, Settings dialog and local sign-out state */

(function () {
  var profileBtn = document.getElementById("sm-profile-btn");
  if (!profileBtn) return;

  var menu = document.createElement("div");
  menu.className = "sm-pop sm-profile-pop";
  menu.id = "sm-profile-pop";
  menu.setAttribute("role", "menu");
  menu.setAttribute("aria-label", "Account");
  menu.hidden = true;
  menu.innerHTML =
    '<div class="sm-pop-body sm-profile-menu">' +
    '<button class="sm-profile-action" id="sm-profile-settings" type="button" role="menuitem"><span class="ico" aria-hidden="true">⚙</span><span>Settings</span></button>' +
    '<button class="sm-profile-action" id="sm-profile-logout" type="button" role="menuitem"><span class="ico" aria-hidden="true">⏻</span><span>Log out</span></button>' +
    '</div>';
  shell.appendChild(menu);

  var settings = document.createElement("div");
  settings.className = "sm-settings-layer";
  settings.id = "sm-settings";
  settings.hidden = true;
  settings.innerHTML =
    '<div class="sm-settings-modal" role="dialog" aria-modal="true" aria-labelledby="sm-settings-title">' +
    '<div class="sm-settings-h"><b id="sm-settings-title">Settings</b><button class="sm-pop-x" id="sm-settings-close" type="button" aria-label="Close settings">×</button></div>' +
    '<div class="sm-settings-body">' +
    '<div class="sm-pop-sec"><span class="sm-pop-label">Appearance</span>' +
    '<div class="sm-profile-theme">' +
    '<button type="button" data-profile-theme="light" aria-pressed="true">Light</button>' +
    '<button type="button" data-profile-theme="dark" aria-pressed="false">Dark</button>' +
    '</div></div>' +
    '<div class="sm-profile-about"><span>Castellan</span><small>v0.1 · local mock</small></div>' +
    '</div></div>';
  shell.appendChild(settings);

  var signedOut = document.createElement("div");
  signedOut.className = "sm-signedout";
  signedOut.id = "sm-signedout";
  signedOut.hidden = true;
  signedOut.innerHTML =
    '<span class="sm-signedout-logo" aria-hidden="true"><img class="signedout-logo-light" src="../logo/LogoLight.svg" alt=""><img class="signedout-logo-dark" src="../logo/LogoDark.svg" alt=""></span>' +
    '<b>You\u2019re signed out</b>' +
    '<p>This is a local mock. Your workspaces and settings are still here.</p>' +
    '<button class="mbtn primary" id="sm-signedout-return" type="button">Return to Castellan</button>';
  shell.appendChild(signedOut);

  var settingsAction = document.getElementById("sm-profile-settings");
  var logoutAction = document.getElementById("sm-profile-logout");
  var settingsClose = document.getElementById("sm-settings-close");
  var themeButtons = settings.querySelectorAll("[data-profile-theme]");
  var signedOutReturn = document.getElementById("sm-signedout-return");

  function isDark() {
    return document.documentElement.dataset.theme === "dark";
  }

  function syncTheme() {
    themeButtons.forEach(function (btn) {
      var on = btn.dataset.profileTheme === (isDark() ? "dark" : "light");
      btn.classList.toggle("on", on);
      btn.setAttribute("aria-pressed", String(on));
    });
  }

  function openProfile() {
    menu.hidden = false;
    profileBtn.setAttribute("aria-expanded", "true");
    positionPop(menu, profileBtn);
    setTimeout(function () { settingsAction.focus(); }, 0);
  }

  function closeProfile() {
    if (menu.hidden) return;
    var hadFocus = menu.contains(document.activeElement);
    menu.hidden = true;
    profileBtn.setAttribute("aria-expanded", "false");
    if (hadFocus) profileBtn.focus();
  }

  function openSettings() {
    closeProfile();
    settings.hidden = false;
    syncTheme();
    setTimeout(function () { settingsClose.focus(); }, 0);
  }

  function closeSettings() {
    if (settings.hidden) return;
    var hadFocus = settings.contains(document.activeElement);
    settings.hidden = true;
    if (hadFocus) profileBtn.focus();
  }

  function showSignedOut() {
    closeProfile();
    signedOut.hidden = false;
    setTimeout(function () { signedOutReturn.focus(); }, 0);
  }

  function hideSignedOut() {
    if (signedOut.hidden) return;
    signedOut.hidden = true;
    profileBtn.focus();
  }

  profileBtn.addEventListener("click", function () {
    if (menu.hidden) openProfile();
    else closeProfile();
  });
  settingsAction.addEventListener("click", openSettings);
  logoutAction.addEventListener("click", showSignedOut);
  settingsClose.addEventListener("click", closeSettings);
  menu.addEventListener("click", function (e) { e.stopPropagation(); });

  themeButtons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      if (window.CastellanTheme) window.CastellanTheme.set(btn.dataset.profileTheme);
      syncTheme();
    });
  });

  settings.addEventListener("click", function (e) {
    if (e.target === settings) closeSettings();
  });
  var settingsModal = settings.querySelector(".sm-settings-modal");
  if (settingsModal) settingsModal.addEventListener("click", function (e) { e.stopPropagation(); });
  signedOutReturn.addEventListener("click", hideSignedOut);

  document.addEventListener("click", function (e) {
    if (menu.hidden) return;
    if (menu.contains(e.target) || profileBtn.contains(e.target)) return;
    closeProfile();
  });

  document.addEventListener("keydown", function (e) {
    if (e.key !== "Escape") return;
    if (!settings.hidden) closeSettings();
    else if (!menu.hidden) closeProfile();
    else if (!signedOut.hidden) hideSignedOut();
  });

  if (window.MutationObserver) {
    new MutationObserver(syncTheme).observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  }
  syncTheme();
})();

/* ================= 70-composer.js ================= */
/* 70-composer — model/effort state, toolbar and composer chips */

  /* ------------------------------------------------------- composers */

  var MODELS = window.CODEX_MODELS || [];
  var EFFORTS = window.CODEX_EFFORTS || {};
  var MODEL_FALLBACK = {
    id: "gpt-5.3-codex", short: "5.3 Codex", label: "GPT-5.3 Codex",
    note: "Codex model", efforts: ["low", "medium", "high"], defaultEffort: "high"
  };

  function modelById(id) {
    for (var i = 0; i < MODELS.length; i++) if (MODELS[i].id === id) return MODELS[i];
    return MODELS[0] || MODEL_FALLBACK;
  }

  function effortById(id) {
    return EFFORTS[id] || { label: id || "High", short: id || "High", note: "" };
  }

  function composerState(box) {
    if (!box.__composer) {
      var first = modelById("");
      box.__composer = {
        model: first.id,
        effort: first.defaultEffort || "high",
        files: [],
        local: []
      };
    }
    var st = box.__composer;
    var m = modelById(st.model);
    if (m.id !== st.model) st.model = m.id;
    if (m.efforts.indexOf(st.effort) === -1) st.effort = m.defaultEffort || m.efforts[0];
    return st;
  }

  function isTempComposer(box) {
    if (!box) return false;
    var v = box.closest ? box.closest(".sm-view") : null;
    return !!v && (v.dataset.smView === "temp" || v.dataset.smView === "temp-new");
  }

  function updateComposerButtons(box) {
    var st = box.__composer;
    if (!st || !st.modelBtn) return;
    var m = modelById(st.model);
    var e = effortById(st.effort);
    st.modelBtn.querySelector(".sm-mlabel").textContent = m.short;
    st.modelBtn.title = "Model: " + m.label;
    st.effortBtn.querySelector(".sm-elabel").textContent = e.short;
    st.effortBtn.title = "Reasoning effort: " + e.label;
  }

  function chipEl(icon, label, title, cls, onRemove) {
    var chip = document.createElement("span");
    chip.className = "sm-ctxchip " + cls;
    chip.title = title || label;
    var ic = document.createElement("span");
    ic.className = "ci";
    ic.textContent = icon;
    var tx = document.createElement("span");
    tx.className = "tx";
    tx.textContent = label;
    var x = document.createElement("button");
    x.type = "button";
    x.className = "x";
    x.textContent = "×";
    x.setAttribute("aria-label", "Remove " + label);
    x.addEventListener("click", function (e) {
      e.stopPropagation();
      onRemove();
    });
    chip.appendChild(ic);
    chip.appendChild(tx);
    chip.appendChild(x);
    return chip;
  }

  function fileSize(bytes) {
    if (!bytes) return "";
    if (bytes < 1024) return bytes + " B";
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
    return (bytes / (1024 * 1024)).toFixed(1) + " MB";
  }

  function renderComposerChips(box) {
    if (!box || !box.__composer || !box.__composer.chips) return;
    var st = box.__composer;
    var wrap = st.chips;
    wrap.innerHTML = "";
    if (isTempComposer(box)) {
      if (tempWs) {
        wrap.appendChild(chipEl("◈", tempWs, "Workspace context · read-only", "ws", function () {
          setTempWorkspace("", box);
        }));
      } else if (tempFolder) {
        var seg = tempFolder.split("/").filter(Boolean);
        wrap.appendChild(chipEl("▸", seg.length ? seg[seg.length - 1] : tempFolder, tempFolder, "folder", function () {
          setTempFolder("", box);
        }));
      }
    }
    st.files.forEach(function (path) {
      var f = fileMeta(path) || {};
      var kind = f.kind || kindOf(path);
      wrap.appendChild(chipEl(iconFor(kind), baseName(path), fullPath(path), "file", function () {
        st.files = st.files.filter(function (p) { return p !== path; });
        renderComposerChips(box);
        if (remotePop && !remotePop.hidden) renderRemote();
      }));
    });
    (st.local || []).forEach(function (file) {
      wrap.appendChild(chipEl("⇪", file.name, "Local file · " + fileSize(file.size), "local", function () {
        st.local = st.local.filter(function (f) { return f !== file; });
        renderComposerChips(box);
      }));
    });
    wrap.hidden = wrap.children.length === 0;
  }

  function renderAllComposerChips() {
    $$(".sm-views .sm-inputbox, .sm-views .sm-bigta", shell).forEach(function (box) {
      if (box.__composer) renderComposerChips(box);
    });
  }

  function enhanceComposers() {
    $$(".sm-views .sm-inputbox, .sm-views .sm-bigta", shell).forEach(function (box) {
      if (box.__composer) return;
      var st = composerState(box);
      var isInput = box.classList.contains("sm-inputbox");
      var plusHTML = '<button class="sm-plusbtn" type="button" aria-label="Add context" title="Add files or context" aria-expanded="false">＋</button>';
      var selectorsHTML =
        '<button class="sm-modelbtn" type="button"><span class="sm-mlabel"></span><i>▾</i></button>' +
        '<button class="sm-effortbtn" type="button"><span class="sm-elabel"></span><i>▾</i></button>' +
        '<button class="sm-ctxusage" type="button" aria-label="Context usage: 68%" aria-haspopup="dialog" aria-expanded="false" title="Context usage · 68%"><span class="ring" style="--pct:68%"></span><span class="pct">68%</span></button>';
      var tools = document.createElement("div");
      tools.className = "sm-compose-tools sm-compose-toolbar";
      var chips = document.createElement("div");
      chips.className = "sm-compose-files";
      chips.hidden = true;

      if (isInput) {
        var ph = $(".ph", box);
        var send = document.createElement("span");
        send.className = "send";
        send.textContent = "↑";
        var row = document.createElement("div");
        row.className = "sm-compose-row";
        row.innerHTML = plusHTML;
        var rowPlus = $(".sm-plusbtn", row);
        if (ph) row.appendChild(ph);
        row.appendChild(send);
        box.appendChild(row);
        box.insertBefore(chips, row);
        tools.innerHTML = selectorsHTML;
        if (box.parentNode) box.parentNode.insertBefore(tools, box.nextSibling);
        st.plus = rowPlus;
      } else {
        tools.innerHTML = plusHTML + selectorsHTML;
        if (box.parentNode) {
          box.parentNode.insertBefore(chips, box.nextSibling);
          box.parentNode.insertBefore(tools, chips.nextSibling);
        }
        st.plus = $(".sm-plusbtn", tools);
      }
      st.tools = tools;
      st.chips = chips;
      st.modelBtn = $(".sm-modelbtn", tools);
      st.effortBtn = $(".sm-effortbtn", tools);
      st.usage = $(".sm-ctxusage", tools);
      updateComposerButtons(box);
      renderComposerChips(box);

      st.plus.addEventListener("click", function (e) {
        e.stopPropagation();
        openAttach(box, st.plus);
      });
      st.modelBtn.addEventListener("click", function (e) {
        e.stopPropagation();
        openSelector(box, st.modelBtn, "model");
      });
      st.effortBtn.addEventListener("click", function (e) {
        e.stopPropagation();
        openSelector(box, st.effortBtn, "effort");
      });
      if (st.usage) {
        st.usage.addEventListener("click", function (e) {
          e.stopPropagation();
          openUsage(st.usage);
        });
      }
    });
    buildPickers();
  }

  var usagePop = null;
  var usageBtn = null;

  function buildUsage() {
    if (usagePop) return;
    usagePop = document.createElement("div");
    usagePop.className = "sm-pop sm-usage-pop";
    usagePop.id = "sm-usage-pop";
    usagePop.setAttribute("role", "dialog");
    usagePop.setAttribute("aria-label", "Context usage");
    usagePop.hidden = true;
    usagePop.innerHTML =
      '<div class="sm-pop-h"><div><b>Context</b><span class="sm-pop-sub">87k / 128k</span></div>' +
      '<button class="sm-pop-x" id="sm-usage-close" type="button" aria-label="Close context usage">×</button></div>' +
      '<div class="sm-usage-body">' +
      '<div class="sm-usage-meter"><i style="width:68%"></i></div>' +
      '<div class="sm-usage-row"><span class="sm-usage-dot" style="background:var(--accent)"></span><span class="nm">Workspace &amp; instructions</span><b>12k</b><small>9%</small></div>' +
      '<div class="sm-usage-row"><span class="sm-usage-dot" style="background:var(--blue)"></span><span class="nm">Open files</span><b>22k</b><small>17%</small></div>' +
      '<div class="sm-usage-row"><span class="sm-usage-dot" style="background:var(--success)"></span><span class="nm">Task thread</span><b>31k</b><small>24%</small></div>' +
      '<div class="sm-usage-row"><span class="sm-usage-dot" style="background:var(--warn)"></span><span class="nm">Tool output</span><b>17k</b><small>13%</small></div>' +
      '<div class="sm-usage-row"><span class="sm-usage-dot" style="background:var(--rose)"></span><span class="nm">Attachments</span><b>5k</b><small>4%</small></div>' +
      '<div class="sm-usage-total"><span>Used</span><b>87k</b><small>68%</small></div>' +
      '<div class="sm-usage-free"><span>Free</span><b>41k</b><small>32%</small></div>' +
      '</div>';
    shell.appendChild(usagePop);
    var close = $("#sm-usage-close", usagePop);
    if (close) close.addEventListener("click", closeUsage);
    usagePop.addEventListener("click", function (e) { e.stopPropagation(); });
    addEventListener("keydown", function (e) {
      if (e.key === "Escape") closeUsage();
    });
    document.addEventListener("click", function (e) {
      if (!usagePop || usagePop.hidden) return;
      if (usagePop.contains(e.target) || (usageBtn && usageBtn.contains(e.target))) return;
      closeUsage();
    });
  }

  function openUsage(btn) {
    buildUsage();
    if (!usagePop || (usageBtn === btn && !usagePop.hidden)) {
      closeUsage();
      return;
    }
    closeUsage();
    usageBtn = btn;
    btn.classList.add("on");
    btn.setAttribute("aria-expanded", "true");
    usagePop.hidden = false;
    positionPop(usagePop, btn, true);
    var close = $("#sm-usage-close", usagePop);
    if (close) setTimeout(function () { close.focus(); }, 0);
  }

  function closeUsage() {
    if (usageBtn) {
      usageBtn.classList.remove("on");
      usageBtn.setAttribute("aria-expanded", "false");
    }
    if (usagePop) usagePop.hidden = true;
    usageBtn = null;
  }

/* ================= 80-pickers.js ================= */
/* 80-pickers — add menu, Upload, Remote chooser, model and effort popovers */

  function buildPickers() {
    if (attachPop) return;

    attachPop = document.createElement("div");
    attachPop.className = "sm-pop sm-add-pop";
    attachPop.id = "sm-attach-pop";
    attachPop.hidden = true;
    attachPop.innerHTML =
      '<div class="sm-add-menu">' +
      '<button class="sm-add-item" id="sm-add-upload" type="button"><span class="ico">⇪</span><span class="sm-add-copy"><b>Upload</b><small>From this device</small></span></button>' +
      '<button class="sm-add-item" id="sm-add-remote" type="button"><span class="ico">▤</span><span class="sm-add-copy"><b>Remote</b><small>From the remote machine</small></span></button>' +
      '</div>';
    shell.appendChild(attachPop);
    attachPop.addEventListener("click", function (e) { e.stopPropagation(); });
    $("#sm-add-upload", attachPop).addEventListener("click", function () {
      closeAttach();
      if (localInput) localInput.click();
    });
    $("#sm-add-remote", attachPop).addEventListener("click", function () {
      closeAttach();
      openRemote(activeComposer);
    });

    localInput = document.createElement("input");
    localInput.type = "file";
    localInput.multiple = true;
    localInput.hidden = true;
    localInput.id = "sm-local-input";
    localInput.addEventListener("change", handleLocalFiles);
    shell.appendChild(localInput);

    remoteBack = document.createElement("div");
    remoteBack.className = "sm-modal-back";
    remoteBack.hidden = true;
    remoteBack.addEventListener("click", closeRemote);
    shell.appendChild(remoteBack);

    remotePop = document.createElement("div");
    remotePop.className = "sm-remote-pop";
    remotePop.id = "sm-remote-pop";
    remotePop.hidden = true;
    remotePop.innerHTML =
      '<div class="sm-remote-h"><div><b>Remote files</b><span class="sm-remote-sub" id="sm-remote-sub"></span></div>' +
      '<button class="sm-pop-x" id="sm-remote-x" type="button" aria-label="Close">×</button></div>' +
      '<div class="sm-remote-body">' +
      '<div class="sm-remote-ctx" id="sm-remote-ctx"><div class="sm-pop-label">Workspace</div><div class="sm-attach-ws" id="sm-remote-ws"></div></div>' +
      '<div class="sm-exp-loc sm-remote-pathbar"><button class="sm-exp-nav" id="sm-remote-up" type="button" aria-label="Up one folder" title="Up one folder">←</button>' +
      '<div class="sm-exp-path" id="sm-remote-path" title="/home/manuel/Downloads/random_projects/codingPlatform">/home/manuel/Downloads/random_projects/codingPlatform</div>' +
      '<button class="sm-exp-nav" id="sm-remote-refresh" type="button" aria-label="Refresh folder" title="Refresh">⟳</button></div>' +
      '<div class="sm-remote-searchrow"><span>⌕</span><input id="sm-remote-search" type="text" autocomplete="off" placeholder="Search files in this folder…"></div>' +
      '<div class="sm-remote-list" id="sm-remote-list"></div>' +
      '</div>' +
      '<div class="sm-remote-f"><span id="sm-remote-count"></span><span class="sp"></span>' +
      '<button class="sm-mini" id="sm-remote-cancel" type="button">Cancel</button>' +
      '<button class="sm-mini primary" id="sm-remote-done" type="button">Attach</button></div>';
    shell.appendChild(remotePop);
    remotePop.addEventListener("click", function (e) { e.stopPropagation(); });
    $("#sm-remote-x", remotePop).addEventListener("click", closeRemote);
    $("#sm-remote-cancel", remotePop).addEventListener("click", closeRemote);
    $("#sm-remote-done", remotePop).addEventListener("click", commitRemote);
    $("#sm-remote-search", remotePop).addEventListener("input", function () {
      clearTimeout(remoteClickTimer);
      remoteSearch = this.value || "";
      renderRemoteFiles();
    });
    $("#sm-remote-up", remotePop).addEventListener("click", function () {
      if (!remoteDir.length) return;
      remoteDir.pop();
      remoteOpenDirs = {};
      remoteSearch = "";
      var search = $("#sm-remote-search", remotePop);
      if (search) search.value = "";
      renderRemote();
    });
    $("#sm-remote-refresh", remotePop).addEventListener("click", function () { renderRemoteFiles(); });

    selectPop = document.createElement("div");
    selectPop.className = "sm-pop sm-select-pop";
    selectPop.id = "sm-select-pop";
    selectPop.hidden = true;
    selectPop.innerHTML =
      '<div class="sm-pop-h"><b id="sm-select-title">Model</b><button class="sm-pop-x" id="sm-select-x" type="button" aria-label="Close">×</button></div>' +
      '<div class="sm-pop-body" id="sm-select-body"></div>' +
      '<div class="sm-pop-f"><span>Applies to this chat only</span></div>';
    shell.appendChild(selectPop);
    selectPop.addEventListener("click", function (e) { e.stopPropagation(); });
    $("#sm-select-x", selectPop).addEventListener("click", closeSelector);

    addEventListener("click", function (e) {
      if (attachPop && !attachPop.hidden && !attachPop.contains(e.target) && e.target !== activeAttachBtn) closeAttach();
      if (selectPop && !selectPop.hidden && !selectPop.contains(e.target) && e.target !== activeSelectBtn) closeSelector();
    });
    addEventListener("keydown", function (e) {
      if (e.key === "Escape") { closeAttach(); closeSelector(); closeRemote(); }
    });
  }

  function positionPop(pop, anchor, forceAbove) {
    if (!pop || !anchor) return;
    pop.hidden = false;
    var rawScale = getComputedStyle(document.documentElement).getPropertyValue("--ui-scale");
    var scale = parseFloat(rawScale);
    if (isNaN(scale) || scale <= 0) scale = 1;
    var r = anchor.getBoundingClientRect();
    var w = pop.offsetWidth * scale;
    var h = pop.offsetHeight * scale;
    var vw = innerWidth;
    var vh = innerHeight;
    var left = Math.max(8, Math.min(r.left, vw - w - 8));
    pop.style.left = (left / scale) + "px";
    if (forceAbove || r.top > h + 14) {
      pop.style.top = "auto";
      pop.style.bottom = ((vh - r.top + 7) / scale) + "px";
    } else {
      pop.style.bottom = "auto";
      pop.style.top = (Math.min(r.bottom + 7, vh - h - 8) / scale) + "px";
    }
  }

  function closeAttach() {
    if (!attachPop) return;
    attachPop.hidden = true;
    if (activeAttachBtn) {
      activeAttachBtn.classList.remove("on");
      activeAttachBtn.setAttribute("aria-expanded", "false");
    }
    activeAttachBtn = null;
  }

  function closeSelector() {
    if (!selectPop) return;
    selectPop.hidden = true;
    if (activeSelectBtn) activeSelectBtn.classList.remove("on");
    activeSelectBtn = null;
    activeSelectKind = null;
  }

  function closeRemote() {
    clearTimeout(remoteClickTimer);
    if (remoteBack) remoteBack.hidden = true;
    if (remotePop) remotePop.hidden = true;
    remotePending = [];
  }

  function closePickers() {
    closeAttach();
    closeSelector();
    closeRemote();
    closeArchiveConfirm();
  }

  function openAttach(box, btn) {
    if (!attachPop) return;
    if (!attachPop.hidden && activeComposer === box) { closeAttach(); return; }
    closeSelector();
    closeRemote();
    if (activeAttachBtn && activeAttachBtn !== btn) {
      activeAttachBtn.classList.remove("on");
      activeAttachBtn.setAttribute("aria-expanded", "false");
    }
    activeComposer = box;
    activeAttachBtn = btn;
    positionPop(attachPop, btn);
    btn.classList.add("on");
    btn.setAttribute("aria-expanded", "true");
  }

  function openSelector(box, btn, kind) {
    if (!selectPop) return;
    if (!selectPop.hidden && activeComposer === box && activeSelectKind === kind) { closeSelector(); return; }
    closeAttach();
    closeRemote();
    if (activeSelectBtn && activeSelectBtn !== btn) activeSelectBtn.classList.remove("on");
    activeComposer = box;
    activeSelectBtn = btn;
    activeSelectKind = kind;
    renderSelector();
    positionPop(selectPop, btn);
    btn.classList.add("on");
  }

  function openRemote(box) {
    if (!box || !remotePop) return;
    closeAttach();
    closeSelector();
    activeComposer = box;
    clearTimeout(remoteClickTimer);
    var tempBox = isTempComposer(box);
    remoteWsId = tempBox ? (tempWs || "") : (currentView === "new" ? lastWorkspace : (currentWs || lastWorkspace || ""));
    remoteDir = [];
    remoteOpenDirs = {};
    remoteSearch = "";
    remotePending = composerState(box).files.slice();
    var search = $("#sm-remote-search", remotePop);
    if (search) search.value = "";
    renderRemote();
    if (remoteBack) remoteBack.hidden = false;
    remotePop.hidden = false;
    if (search) setTimeout(function () { search.focus(); }, 0);
  }

  function handleLocalFiles() {
    if (!activeComposer || !localInput) return;
    var st = composerState(activeComposer);
    Array.prototype.forEach.call(localInput.files || [], function (file) {
      var exists = (st.local || []).some(function (f) { return f.name === file.name && f.size === file.size; });
      if (!exists) st.local.push({ name: file.name, size: file.size, type: file.type || "" });
    });
    renderComposerChips(activeComposer);
    localInput.value = "";
  }

  function commitRemote() {
    if (activeComposer) {
      var st = composerState(activeComposer);
      st.files = remotePending.slice();
      renderComposerChips(activeComposer);
    }
    closeRemote();
  }

  function remoteRootPath() {
    var d = remoteWsId && WS[remoteWsId];
    return (d && d.path) || "/home/manuel/Downloads/random_projects/codingPlatform";
  }

  function remoteFullPath() {
    var root = remoteRootPath().replace(/\/$/, "");
    return root + (remoteDir.length ? "/" + remoteDir.join("/") : "");
  }

  function remoteNode() {
    var node = treeRoot;
    for (var i = 0; i < remoteDir.length; i++) {
      var next = null;
      (node.children || []).some(function (c) {
        if (c.type === "dir" && c.name === remoteDir[i]) { next = c; return true; }
        return false;
      });
      if (!next) { remoteDir = remoteDir.slice(0, i); break; }
      node = next;
    }
    return node || treeRoot;
  }

  function renderRemotePath() {
    var p = $("#sm-remote-path", remotePop);
    var full = remoteFullPath();
    if (p) { p.textContent = full; p.title = full; p.scrollLeft = 0; }
    var up = $("#sm-remote-up", remotePop);
    if (up) up.disabled = remoteDir.length === 0;
  }

  function remoteFileRow(path, depth, parentLabel) {
    var st = composerState(activeComposer);
    var f = fileMap[path] || {};
    var kind = f.kind || kindOf(path);
    var on = remotePending.indexOf(path) !== -1;
    var row = document.createElement("button");
    row.type = "button";
    row.className = "sm-exp-row file" + (on ? " on" : "");
    row.style.paddingLeft = (5 + depth * 11) + "px";
    row.title = remoteRootPath().replace(/\/$/, "") + path;
    row.innerHTML = '<span class="ico">' + iconFor(kind) + '</span><span class="nm">' + esc(baseName(path)) + '</span>' +
      (parentLabel ? '<span class="sm-remote-parent">' + esc(parentLabel) + '</span>' : '') +
      '<span class="meta">' + esc(f.size || "") + '</span><span class="sm-remote-check">' + (on ? "✓" : "＋") + '</span>';
    row.addEventListener("click", function () {
      clearTimeout(remoteClickTimer);
      var idx = remotePending.indexOf(path);
      if (idx === -1) remotePending.push(path);
      else remotePending = remotePending.filter(function (p) { return p !== path; });
      on = !on;
      row.classList.toggle("on", on);
      row.querySelector(".sm-remote-check").textContent = on ? "✓" : "＋";
      updateRemoteCount();
    });
    row.addEventListener("dblclick", function (e) {
      e.preventDefault();
      if (remotePending.indexOf(path) === -1) remotePending.push(path);
      row.classList.add("on");
      row.querySelector(".sm-remote-check").textContent = "✓";
      updateRemoteCount();
    });
    return row;
  }

  function renderRemoteSearch(q) {
    var list = $("#sm-remote-list", remotePop);
    list.innerHTML = "";
    var node = remoteNode();
    var base = remoteDir.length ? "/" + remoteDir.join("/") : "";
    var matches = [];
    function walk(n, rel) {
      (n.children || []).forEach(function (c) {
        var next = rel + "/" + c.name;
        if (c.type === "dir") walk(c, next);
        else if (next.toLowerCase().indexOf(q) !== -1 || c.name.toLowerCase().indexOf(q) !== -1) matches.push({ path: c.path, rel: next });
      });
    }
    walk(node, base);
    matches.sort(function (a, b) { return a.rel.localeCompare(b.rel); }).forEach(function (m) {
      var parent = m.rel.split("/").slice(0, -1).join("/") || "/";
      list.appendChild(remoteFileRow(m.path, 0, parent));
    });
    if (!matches.length) {
      var empty = document.createElement("div");
      empty.className = "sm-remote-empty";
      empty.textContent = "No files match that search.";
      list.appendChild(empty);
    }
    updateRemoteCount();
  }

  function renderRemote() {
    if (!activeComposer || !remotePop) return;
    var temp = isTempComposer(activeComposer);
    var sub = $("#sm-remote-sub", remotePop);
    if (sub) sub.textContent = temp ? "optional context · read-only" : ((currentWs || lastWorkspace) + " · read-only");
    show($("#sm-remote-ctx", remotePop), temp);
    if (temp) {
      var wsWrap = $("#sm-remote-ws", remotePop);
      wsWrap.innerHTML = "";
      var choices = [{ id: "", label: "No context" }].concat(Object.keys(WS).map(function (id) { return { id: id, label: id }; }));
      choices.forEach(function (c) {
        var b = document.createElement("button");
        b.type = "button";
        b.className = "sm-wschoice" + ((tempWs || "") === c.id ? " on" : "");
        b.textContent = c.label;
        b.addEventListener("click", function () { setTempWorkspace(c.id, activeComposer); });
        wsWrap.appendChild(b);
      });
    }
    renderRemotePath();
    renderRemoteFiles();
  }

  function renderRemoteFiles() {
    if (!activeComposer || !remotePop) return;
    var list = $("#sm-remote-list", remotePop);
    if (!list) return;
    var q = (remoteSearch || "").trim().toLowerCase();
    if (q) { renderRemoteSearch(q); return; }
    var node = remoteNode();
    var base = remoteDir.length ? "/" + remoteDir.join("/") : "";
    list.innerHTML = "";
    var count = 0;

    function walk(n, depth, relBase) {
      var items = (n.children || []).slice().sort(function (a, b) {
        if (a.type !== b.type) return a.type === "dir" ? -1 : 1;
        return a.name.localeCompare(b.name);
      });
      items.forEach(function (c) {
        var rel = relBase + "/" + c.name;
        if (c.type === "dir") {
          var open = !!remoteOpenDirs[rel];
          var row = document.createElement("button");
          row.type = "button";
          row.className = "sm-exp-row dir" + (open ? " open" : "");
          row.style.paddingLeft = (5 + depth * 11) + "px";
          row.setAttribute("aria-expanded", String(open));
          row.title = remoteRootPath().replace(/\/$/, "") + rel;
          row.innerHTML = '<span class="ico">' + (open ? "▾" : "▸") + '</span><span class="nm">' + esc(c.name) + '</span><span class="meta">folder</span>';
          row.addEventListener("click", function () {
            clearTimeout(remoteClickTimer);
            remoteClickTimer = setTimeout(function () {
              if (remoteOpenDirs[rel]) delete remoteOpenDirs[rel];
              else remoteOpenDirs[rel] = true;
              renderRemoteFiles();
            }, 220);
          });
          row.addEventListener("dblclick", function (e) {
            e.preventDefault();
            clearTimeout(remoteClickTimer);
            remoteDir = rel.split("/").filter(Boolean);
            remoteOpenDirs = {};
            remoteSearch = "";
            var search = $("#sm-remote-search", remotePop);
            if (search) search.value = "";
            renderRemote();
          });
          list.appendChild(row);
          count++;
          if (open) walk(c, depth + 1, rel);
        } else {
          list.appendChild(remoteFileRow(c.path, depth, ""));
          count++;
        }
      });
    }

    walk(node, 0, base);
    if (!count) {
      var empty = document.createElement("div");
      empty.className = "sm-remote-empty";
      empty.textContent = "This folder is empty.";
      list.appendChild(empty);
    }
    updateRemoteCount();
  }

  function updateRemoteCount() {
    if (!activeComposer || !remotePop) return;
    var st = composerState(activeComposer);
    var el = $("#sm-remote-count", remotePop);
    if (el) {
      var n = remotePending.length;
      var local = st.local.length;
      el.textContent = (n ? n + " selected" : "No files selected") + (local ? " · " + local + " local" : "");
    }
  }

  function renderSelector() {
    if (!activeComposer || !selectPop) return;
    var st = composerState(activeComposer);
    var m = modelById(st.model);
    var title = $("#sm-select-title", selectPop);
    var body = $("#sm-select-body", selectPop);
    if (title) title.textContent = activeSelectKind === "model" ? "Model" : "Reasoning effort";
    if (body) {
      body.innerHTML = "";
      if (activeSelectKind === "model") {
        MODELS.forEach(function (item) {
          var on = item.id === st.model;
          var row = document.createElement("button");
          row.type = "button";
          row.className = "sm-select-row" + (on ? " on" : "");
          row.innerHTML = '<span class="sm-sr-main"><b>' + esc(item.label) + '</b><small>' + esc(item.note) + '</small></span><span class="sm-sr-check">' + (on ? "✓" : "") + "</span>";
          row.addEventListener("click", function () { chooseModel(item.id); });
          body.appendChild(row);
        });
      } else {
        m.efforts.forEach(function (id) {
          var on = id === st.effort;
          var e = effortById(id);
          var row = document.createElement("button");
          row.type = "button";
          row.className = "sm-select-row" + (on ? " on" : "");
          row.innerHTML = '<span class="sm-sr-main"><b>' + esc(e.label) + '</b><small>' + esc(e.note) + '</small></span><span class="sm-sr-check">' + (on ? "✓" : "") + "</span>";
          row.addEventListener("click", function () { chooseEffort(id); });
          body.appendChild(row);
        });
      }
    }
    var foot = $(".sm-pop-f span", selectPop);
    if (foot) foot.textContent = activeSelectKind === "model" ? "Reasoning: " + effortById(st.effort).label : m.label;
  }

  function chooseModel(id) {
    if (!activeComposer) return;
    var st = composerState(activeComposer);
    var m = modelById(id);
    st.model = m.id;
    if (m.efforts.indexOf(st.effort) === -1) st.effort = m.defaultEffort || m.efforts[0];
    updateComposerButtons(activeComposer);
    closeSelector();
  }

  function chooseEffort(id) {
    if (!activeComposer) return;
    var st = composerState(activeComposer);
    var m = modelById(st.model);
    if (m.efforts.indexOf(id) === -1) return;
    st.effort = id;
    updateComposerButtons(activeComposer);
    closeSelector();
  }

/* ================= 90-resizing.js ================= */
/* 90-resizing — left/right rail drag sizing */

  /* -------------------------------------------------------------- resizing */

  function readWidth(key, fallback, min, max) {
    var n = NaN;
    try { n = parseFloat(localStorage.getItem(key)); } catch (e) {}
    if (!isFinite(n)) return fallback;
    return Math.max(min, Math.min(max, n));
  }

  function saveWidth(key, value) {
    try { localStorage.setItem(key, String(Math.round(value))); } catch (e) {}
  }

  var leftW = readWidth("mock-left-w", 214, 176, 320);
  var rightW = readWidth("mock-right-w", 288, 240, 400);
  shell.style.setProperty("--left-w", leftW + "px");
  shell.style.setProperty("--right-w", rightW + "px");

  function bindResizer(el, side) {
    if (!el) return;
    el.addEventListener("pointerdown", function (e) {
      if (side === "left" && shellmock.classList.contains("nav-collapsed")) return;
      e.preventDefault();
      var startX = e.clientX;
      var appW = shellmock.getBoundingClientRect().width;
      var sideEl = $(".sm-side", shell);
      var startW = side === "left" ? sideEl.getBoundingClientRect().width : ctxPanel.getBoundingClientRect().width;
      document.body.classList.add("resizing");

      function move(ev) {
        var dx = ev.clientX - startX;
        var w = side === "left" ? startW + dx : startW - dx;
        if (side === "left") {
          var ctxW = ctxPanel && !ctxPanel.hidden ? ctxPanel.getBoundingClientRect().width : 0;
          var max = Math.min(320, Math.max(176, appW - ctxW - 300));
          w = Math.max(176, Math.min(max, w));
          shell.style.setProperty("--left-w", w + "px");
        } else {
          var leftNow = sideEl.getBoundingClientRect().width;
          var maxR = Math.min(400, Math.max(240, appW - leftNow - 300));
          w = Math.max(240, Math.min(maxR, w));
          shell.style.setProperty("--right-w", w + "px");
        }
      }
      function up() {
        document.removeEventListener("pointermove", move);
        document.removeEventListener("pointerup", up);
        document.body.classList.remove("resizing");
        var final = side === "left" ? sideEl.getBoundingClientRect().width : ctxPanel.getBoundingClientRect().width;
        saveWidth(side === "left" ? "mock-left-w" : "mock-right-w", final);
      }
      document.addEventListener("pointermove", move);
      document.addEventListener("pointerup", up, { once: false });
    });
  }

  bindResizer($("#sm-resize-left", shell), "left");
  bindResizer($("#sm-resize-right", shell), "right");

